VALUES (gen_random_uuid()::text, $q$chess-run-educational-runner$q$, $q$Chess Run$q$, $q$A fast-paced runner and strategy hybrid where chess piece movement rules meet the momentum of an endless runner. Adaptive difficulty and interactive tutorials teach the rules as you play.$q$, $q$Platformer & Arcade$q$, ARRAY[$q$Educational$q$, $q$Runner$q$, $q$Chess$q$, $q$Endless Runner$q$, $q$Adaptive Difficulty$q$]::text[], $q$Unity, C#$q$, $q$2025$q$, $q$♟️$q$, $q$#3f6212$q$, true, 17, $q$GAME$q$, $q$COMPANY$q$, $q$Game developer$q$, $q$Worked as one of two developers on a small team with a technical lead and a game designer.$q$, ARRAY[]::text[], ARRAY[$q$Technical lead$q$, $q$Me, developer$q$, $q$One game designer$q$]::text[], NULL, ARRAY[$q$Chess piece movement rules applied to endless running$q$, $q$Adaptive difficulty$q$, $q$Interactive tutorials$q$]::text[], ARRAY[]::text[], NULL, false, CURRENT_TIMESTAMP)
