INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$water-sort-puzzle$q$, $q$Water Sort Puzzle$q$, $q$A commercially released mobile puzzle game about sorting coloured liquids into matching test tubes. It ships with an in-Unity level editor for creating new content, shader-driven liquid, haptic feedback and solvable level generation.$q$, $q$Casual & Puzzle$q$, ARRAY[$q$Casual$q$, $q$Puzzle$q$, $q$Level Editor$q$, $q$Mobile Monetization$q$, $q$Shader Graph$q$, $q$Haptic Feedback$q$]::text[], $q$Unity 6, C#, AppLovin MAX, Unity IAP, Feel Haptics, DOTween, URP$q$, $q$2026$q$, $q$🧪$q$, $q$#0284c7$q$, true, 0, $q$GAME$q$, $q$COMPANY$q$, $q$Game developer$q$, $q$Worked as one of two developers on a small team with a technical lead and a game designer. I built the ad strategy: how rewarded, interstitial and banner ads are placed, plus the ad removal and coin purchases.$q$, ARRAY[$q$Ad strategy: rewarded, interstitial and banner ad placement through AppLovin MAX$q$, $q$In-app purchases for ad removal and coins with Unity IAP$q$, $q$Monetisation compliance: reward verification, network retries, and GDPR and ATT consent flows$q$]::text[], ARRAY[$q$Technical lead$q$, $q$Me, developer$q$, $q$One game designer$q$]::text[], NULL, ARRAY[$q$Procedural pouring with angle and wobble physics$q$, $q$In-Unity level editor for creating new levels$q$, $q$Algorithmically solvable stages$q$, $q$Rewarded ads and in-app purchases$q$, $q$Customisation store for tubes, fluids and backgrounds$q$, $q$Haptic feedback and celebratory effects$q$]::text[], ARRAY[$q$Level editor built inside Unity so new content needs no code changes$q$, $q$Shader-driven liquid: surfaces stay level as tubes tilt, and pour streams follow bezier curves matched to colour layers$q$, $q$Solvability guarantee: levels are reverse-shuffled and verified before saving$q$]::text[], $q$Android, iOS$q$, false, CURRENT_TIMESTAMP)
